        assert.equal(h.opsOf('scm.addLabel')[0].label, 'pr_approved');
        assert.equal(h.opsOf('scm.addLabel')[1].number, 42);
        assert.equal(h.opsOf('scm.addLabel')[1].label, 'ai_pr_reviewed');
