        assert.equal(mod.deriveProjectKey({ configPath: '.dmtools/config.js' }), '');
        assert.equal(mod.deriveProjectKey({ configPath: 'config.js' }), '');
        assert.equal(mod.deriveProjectKey({ configPath: '' }), '');
    });

