    try {
        const content = outputFiles.readOutputFile(filePath, {
            ticketKey: ticketKey,
            workingDir: workingDir
        });
        if (content && content.trim() !== '') {
            return content;
        }
    } catch (error) {
        console.warn('Could not read file ' + filePath + ':', error);
    }
