        assert.equal(mod.isFileDeletedInDiff(diff, 'missing.js'), false);
        assert.equal(mod.isFileDeletedInDiff(null, 'gone.js'), false);
        assert.equal(mod.isFileDeletedInDiff(diff, ''), false);
    });

