        var withMeta = 'diff --git a/a.js b/a.js\n--- a/a.js\n+++ b/a.js\nindex aaa..bbb 100644\n@@ -1 +1 @@\n-x\n+y\n';
        assert.deepEqual(mod.parseDiffLineInfo(withMeta, 'a.js', 1), { present: true, side: 'RIGHT' });

